50	export type HexUploaderType = 'JLink' | 'STVP' | 'STLink' | 'stcgal' | 'pyOCD' | 'OpenOCD' | 'probe-rs' | 'Custom';
51	
52	export interface UploadOption {
53	    // program file path
54	    // format: "<file1_path>[,addr1];<file2_path>[,addr2]"
55	    bin: string;
