65	export class HexUploaderManager {
66	
67	    private uploaderList: HexUploaderInfo[] = [];
68	
69	    private constructor() {
70	
71	        const arm_toolchains   = ToolchainManager.getInstance().getToolchainNameList('ARM');
72	        const riscv_toolchains = ToolchainManager.getInstance().getToolchainNameList('RISC-V');
73	
74	        this.uploaderList = [
75	            {
76	                type: 'JLink',
77	                description: 'for Cortex-M chips, only JLink interface',
78	                filters: arm_toolchains.concat(riscv_toolchains, ['ANY_GCC'])
79	            },
80	            {
81	                type: 'STLink',
82	                description: 'for STM32 chips, only STLink interface',
83	                filters: arm_toolchains
84	            },
85	            {
86	                type: 'pyOCD',
87	                description: 'for Cortex-M chips',
88	                filters: arm_toolchains.concat(riscv_toolchains, ['ANY_GCC'])
89	            },
90	            {
91	                type: 'OpenOCD',
92	                description: 'for Cortex-M chips',
93	                filters: arm_toolchains.concat(riscv_toolchains, ['ANY_GCC'])
94	            },
95	            {
96	                type: 'probe-rs',
97	                description: 'for ARM, RISC-V devices',
98	                filters: arm_toolchains.concat(riscv_toolchains, ['ANY_GCC'])
99	            },
100	            // 8/16 bits mcus
101	            {
102	                type: 'stcgal',
103	                description: 'for STC chips',
104	                filters: ['Keil_C51', 'SDCC', 'GNU_SDCC_MCS51']
105	            },
106	            {
107	                type: 'STVP',
108	                description: 'for STM8 chips, only STLink interface',
109	                filters: ['IAR_STM8', 'SDCC', 'COSMIC_STM8']
110	            },
111	            // custom
112	            {
113	                type: 'Custom',
114	                label: 'Custom CLI',
115	                description: 'download program by custom command-line'
116	            }
117	        ];
118	    }
119	
120	    getUploaderLabelByName(uploaderName: HexUploaderType): string {
121	
122	        const index = this.uploaderList.findIndex((info) => {
123	            return info.type == uploaderName;
124	        });
125	
126	        if (index != -1) {
127	            return this.uploaderList[index].label || uploaderName;
128	        }
129	
130	        return uploaderName;
131	    }
132	
133	    getUploaderList(toolType: ToolchainName): HexUploaderInfo[] {
134	        return this.uploaderList.filter((info) => {
135	            return info.filters ? info.filters.includes(toolType) : true;
136	        });
137	    }
138	
139	    createUploader(prj: AbstractProject): HexUploader<any> {
140	        switch (prj.GetConfiguration().config.uploader) {
141	            case 'JLink':
142	                return new JLinkUploader(prj);
143	            case 'STLink':
144	                return new STLinkUploader(prj);
145	            case 'stcgal':
146	                return new StcgalUploader(prj);
147	            case 'STVP':
148	                return new STVPHexUploader(prj);
149	            case 'pyOCD':
150	                return new PyOCDUploader(prj);
151	            case 'OpenOCD':
152	                return new OpenOCDUploader(prj);
153	            case 'probe-rs':
154	                return new ProbeRSUploader(prj);
155	            case 'Custom':
156	                return new CustomUploader(prj);
157	            default:
158	                throw new Error('Invalid uploader type !');
159	        }
160	    }
161	
162	    static getInstance(): HexUploaderManager {
163	        if (_mInstance === undefined) {
164	            _mInstance = new HexUploaderManager();
165	        }
166	        return _mInstance;
167	    }
168	}
