171	
172	interface UploaderPreData<T> {
173	
174	    isOk: boolean | Error;
175	
176	    params?: T;
177	}
178	
179	export interface FlashProgramFile {
180	
181	    path: string;
182	
183	    addr?: string;
184	};
185	
186	export abstract class HexUploader<InvokeParamsType> {
187	
188	    abstract readonly toolType: HexUploaderType;
189	
190	    protected DEF_BIN_ADDR: string = '0x00000000';
191	
192	    protected project: AbstractProject;
193	    protected shellPath: string | undefined;
194	
195	    constructor(prj: AbstractProject) {
196	        this.project = prj;
197	        this.shellPath = ResManager.checkWindowsShell() ? undefined : ResManager.GetInstance().getCMDPath();
198	    }
199	
200	    async upload(eraseAll?: boolean) {
201	
202	        const dat = await this._prepare(eraseAll);
203	
204	        if (dat.isOk === false) { // canceled
205	            return;
206	        }
207	
208	        else if (dat.isOk instanceof Error) { // has a error
209	            throw dat.isOk;
210	        }
211	
212	        // start program
213	        this._launch(dat.params);
214	    }
215	
216	    protected getUploadOptions<T extends UploadOption>(): T {
217	        return JSON.parse(JSON.stringify(this.project.GetConfiguration().uploadConfigModel.data));
218	    }
219	
220	    protected parseProgramFiles<T extends UploadOption>(options: T): FlashProgramFile[] {
221	
222	        const result: FlashProgramFile[] = [];
223	        const matcher = /(?<path>[^,]+)(?:,(?<addr>0x[a-f0-9]+))?/i;
224	
225	        const formatBinFilePath = (p: string): string => {
226	            if (this.toolType == 'STLink') {
227	                // 对于不支持中文路径的烧录器，暂时不要转换为绝对路径
228	                return this.project.resolveEnvVar(p);
229	            } else {
230	                return this.project.toAbsolutePath(p);
231	            }
232	        };
233	
234	        // if 'bin' path is empty, use default program path 
235	        if (options.bin.trim() === '') {
236	
237	            // Fix: Use this.project.getExecutablePathWithoutSuffix() to unify output file path calculation.
238	            const hexPath = [
239	                '.', this.project.getExecutablePathWithoutSuffix() + '.hex'
240	            ].join(File.sep);
241	
242	            return [{ path: formatBinFilePath(hexPath) }];
243	        }
244	
245	        options.bin.split(';').forEach((path) => {
246	            const m = matcher.exec(path);
247	            if (m && m.groups && m.groups['path']) {
248	                result.push({
249	                    path: formatBinFilePath(m.groups['path']),
250	                    addr: m.groups['addr']
251	                });
252	            }
253	        });
254	
255	        return result;
256	    }
257	
258	    resolveHexFilePathEnvs(input: string, programs: FlashProgramFile[]): string {
259	
260	        let portList: string[] = [];
261	        try {
262	            portList = ResManager.GetInstance().enumSerialPort();
263	        } catch (error) {
264	            GlobalEvent.log_error(error);
265	        }
266	
267	        let commandLine = input
268	            .replace(/\$\{hexFile\}|\$\{binFile\}|\$\{programFile\}/ig, programs[0].path)
269	            .replace(/\$\{port\}/ig, portList[0] || '')
270	            .replace(/\$\{portList\}/ig, portList.join(' '))
271	            .replace('${port[0]}', portList[0] || '')
272	            .replace('${port[1]}', portList[1] || '')
273	            .replace('${port[2]}', portList[2] || '')
274	            .replace('${port[3]}', portList[3] || '');
275	
276	        programs.forEach((file, index) => {
277	
278	            commandLine = commandLine
279	                .replace(new RegExp(String.raw`\$\{hexFile\[${index}\]\}`, 'ig'), file.path)
280	                .replace(new RegExp(String.raw`\$\{binFile\[${index}\]\}`, 'ig'), file.path)
281	                .replace(new RegExp(String.raw`\$\{programFile\[${index}\]\}`, 'ig'), file.path);
282	
283	            if (file.addr) {
284	                commandLine = commandLine
285	                    .replace(new RegExp(String.raw`\$\{binAddr\[${index}\]\}`, 'ig'), file.addr || '0x00000000')
286	            }
287	        });
288	
289	        return commandLine;
290	    }
291	
292	    getAllProgramFiles(): FlashProgramFile[] {
293	        return this.parseProgramFiles(this.getUploadOptions<any>());
294	    }
295	
296	    async executeShellCommand(title: string, commandLine: string, env?: any, useTerminal?: boolean, cwd?: string) {
297	        const silent = SettingManager.GetInstance().isSilentBuildOrFlash();
298	        const etask = await sendCommandToTerminal(title, commandLine, {
299	            source: 'eide.flasher',
300	            env: env,
301	            useTerminal: useTerminal,
302	            cwd: cwd,
303	            silent: silent
304	        });
305	        const bar = StatusBarManager.getInstance().get('flash');
306	        if (etask && bar) {
307	            bar.text = `$(loading~spin) Flashing`;
308	            bar.tooltip = `Command: ${commandLine}`;
309	        }
310	    }
311	
312	    protected toAbsolute(_path: string): File | undefined {
313	        if (_path.trim() == '') return undefined;
314	        return new File(this.project.ToAbsolutePath(_path));
315	    }
316	
317	    protected abstract _prepare(eraseAll?: boolean): Promise<UploaderPreData<InvokeParamsType>>;
318	
319	    protected abstract _launch(params: InvokeParamsType | undefined): void;
320	}
