324	/**
325	 * jlink programer
326	*/
327	export enum JLinkProtocolType {
328	    JTAG = 0,
329	    SWD = 1,
330	    FINE = 3,
331	    cJTAG = 7
332	}
333	
334	export interface CPUInfo {
335	    vendor: string;
336	    cpuName: string;
337	}
338	
339	export interface JLinkOptions extends UploadOption {
340	
341	    baseAddr?: string;
342	
343	    cpuInfo: CPUInfo;
344	
345	    proType: JLinkProtocolType;
346	
347	    speed?: number;
348	
349	    otherCmds: string;
350	}
351	
352	class JLinkUploader extends HexUploader<any> {
353	
354	    toolType: HexUploaderType = 'JLink';
355	
356	    protected async _prepare(eraseAll?: boolean): Promise<UploaderPreData<string[]>> {
357	
358	        if (!new File(SettingManager.GetInstance().getJlinkDir()).IsDir()) {
359	            await ResInstaller.instance().setOrInstallTools(this.toolType, `Not found 'JLink' install directory !`);
360	            return { isOk: false };
361	        }
362	
363	        // create output dir
364	        const outFolder = new File(this.project.ToAbsolutePath(this.project.getOutputDir()));
365	        outFolder.CreateDir(true);
366	        const jlinkCommandsFile = File.fromArray([outFolder.path, 'commands.jlink']);
367	
368	        const option = this.getUploadOptions<JLinkOptions>();
369	        const files = this.parseProgramFiles(option);
370	
371	        // jlink cmd template
372	        let jlinkCommandtemplate: string = '${EIDE_JLINK_FLASHER_CMD}';
373	        const tFile = File.fromArray([this.project.getEideDir().path, 'jlink.flasher.cmd.template']);
374	        if (tFile.IsFile()) {
375	            jlinkCommandtemplate = tFile.Read();
376	        }
377	
378	        // program cmds
379	        const flasherCmds: string[] = [];
380	
381	        if (!eraseAll) {
382	
383	            if (files.length == 0) {
384	                return { isOk: new Error(`no any program files !`) };
385	            }
386	
387	            flasherCmds.push(
388	                'r',
389	                'halt'
390	            );
391	
392	            files.forEach((file) => {
393	                if (/\.bin$/i.test(file.path)) {
394	                    const addr = file.addr || option.baseAddr
395	                    flasherCmds.push(`loadfile "${file.path}"${addr ? (`,${addr}`) : ''}`);
396	                } else {
397	                    flasherCmds.push(`loadfile "${file.path}"`);
398	                }
399	            });
400	
401	            flasherCmds.push(
402	                'r',
403	                'go'
404	            );
405	        }
406	
407	        // erase internal falsh
408	        else {
409	            flasherCmds.push(
410	                'r',
411	                'halt',
412	                'erase',
413	                'r'
414	            );
415	        }
416	
417	        // replace vars
418	        jlinkCommandtemplate = jlinkCommandtemplate.replace(/\$\{EIDE_JLINK_FLASHER_CMD\}/g, flasherCmds.join(os.EOL));
419	        jlinkCommandtemplate = this.resolveHexFilePathEnvs(jlinkCommandtemplate, files);
420	        jlinkCommandtemplate = this.project.resolveEnvVar(jlinkCommandtemplate);
421	        jlinkCommandtemplate = jlinkCommandtemplate + os.EOL + 'exit'; // append 'exit' command
422	
423	        const codePage = ResManager.getLocalCodePage();
424	
425	        // write commands file
426	        if (codePage && EncodingConverter.existCode(codePage)) {
427	            fs.writeFileSync(jlinkCommandsFile.path, EncodingConverter.toTargetCode(jlinkCommandtemplate, codePage));
428	        } else {
429	            jlinkCommandsFile.Write(jlinkCommandtemplate);
430	        }
431	
432	        // -AutoConnect 1 -Device <DevName> -If <Interface> -Speed <value> -CommandFile <file>
433	        const cmdList: string[] = [
434	            '-ExitOnError', '1',
435	            '-AutoConnect', '1',
436	            '-Device', option.cpuInfo.cpuName,
437	            '-If', JLinkProtocolType[option.proType],
438	            '-Speed', `${option.speed || 4000}`,
439	            '-CommandFile', jlinkCommandsFile.path
440	        ];
441	
442	        if ([JLinkProtocolType.JTAG, JLinkProtocolType.cJTAG].includes(option.proType)) {
443	            cmdList.push('-JTAGConf', '-1,-1');
444	        }
445	
446	        return {
447	            isOk: true,
448	            params: cmdList
449	        };
450	    }
451	
452	    protected _launch(commandLines: string[]): void {
453	        const jlinkExePath = SettingManager.instance().getJlinkExePath();
454	        const option = this.getUploadOptions<JLinkOptions>();
455	        const commandLine = CmdLineHandler.getCommandLine(jlinkExePath, commandLines);
456	        this.executeShellCommand(this.toolType, `${commandLine} ${option.otherCmds || ''}`.trimEnd());
457	    }
458	}
