460	/**
461	 * stcgal programer
462	*/
463	export interface StcgalFlashOption extends UploadOption {
464	    eepromImgPath: string;
465	    options: string;
466	    extraOptions: string;
467	}
468	
469	class StcgalUploader extends HexUploader<string[]> {
470	
471	    toolType: HexUploaderType = 'stcgal';
472	
473	    static readonly optionKeyMap: { [key: string]: string } = {
474	        'device': '-P',
475	        'port': '-p',
476	        'baudrate': '-b',
477	        'oscFreq': '-t',
478	        'handshakeBaudrate': '-l',
479	        'option': '-o'
480	    };
481	
482	    constructor(prj: AbstractProject) {
483	        super(prj);
484	    }
485	
486	    protected async _prepare(eraseAll?: boolean): Promise<UploaderPreData<string[]>> {
487	
488	        if (eraseAll) {
489	            GlobalEvent.emit('msg', newMessage('Warning', `not support 'Erase Chip' for '${this.toolType}' flasher`));
490	            return { isOk: false };
491	        }
492	
493	        const resManager = ResManager.GetInstance();
494	
495	        let portList: string[];
496	        try {
497	            portList = resManager.enumSerialPort();
498	        } catch (error) {
499	            GlobalEvent.emit('error', error);
500	            return { isOk: false };
501	        }
502	
503	        if (portList.length === 0) {
504	            vscode.window.showWarningMessage('Not found any serialport !');
505	            return { isOk: false };
506	        }
507	
508	        let option: any = Object.create(null);
509	
510	        const opFile = new File(this.project.ToAbsolutePath(this.getUploadOptions<StcgalFlashOption>().options));
511	        if (opFile.IsFile()) {
512	            try {
513	                option = JSON.parse(opFile.Read());
514	            } catch (error) {
515	                GlobalEvent.emit('msg', {
516	                    type: 'Warning',
517	                    contentType: 'string',
518	                    content: 'Invalid flash option file !'
519	                });
520	            }
521	        }
522	
523	        // not found port OR invalid port
524	        if (!option['port'] || !portList.includes(option['port'])) {
525	            if (portList.length > 1) {
526	                const port = await vscode.window.showQuickPick(portList, {
527	                    placeHolder: 'select a serialport to connect',
528	                    canPickMany: false
529	                });
530	                if (!port) {
531	                    return { isOk: false };
532	                }
533	                option['port'] = port;
534	            } else {
535	                option['port'] = portList[0];
536	            }
537	        }
538	
539	        const commands: string[] = [];
540	
541	        for (const key in option) {
542	
543	            if (typeof option[key] === 'number') {
544	                option[key] = (<number>option[key]).toString();
545	            }
546	
547	            if (option[key] !== '') {
548	                if (key === 'option') {
549	                    if (typeof option[key] === 'object') {
550	                        const devOption = option[key];
551	                        for (const key in devOption) {
552	                            if (typeof devOption[key] === 'number') {
553	                                devOption[key] = (<number>devOption[key]).toString();
554	                            }
555	                            if (devOption[key] !== '') {
556	                                commands.push('-o ' + key + '=' + devOption[key]);
557	                            }
558	                        }
559	                    }
560	                } else if (StcgalUploader.optionKeyMap[key]) {
561	                    commands.push(StcgalUploader.optionKeyMap[key] + ' ' + option[key]);
562	                }
563	            }
564	        }
565	
566	        return {
567	            isOk: true,
568	            params: commands
569	        };
570	    }
571	
572	    protected _launch(commands: string[]): void {
573	
574	        const option = this.getUploadOptions<StcgalFlashOption>();
575	        const programs = this.parseProgramFiles(option);
576	
577	        if (programs.length == 0) {
578	            throw new Error(`no any program files !`);
579	        }
580	
581	        commands.push('"' + programs[0].path + '"');
582	
583	        const eepromFile = this.toAbsolute(option.eepromImgPath);
584	        if (eepromFile && eepromFile.IsFile()) {
585	            commands.push('"' + eepromFile.path + '"');
586	        }
587	
588	        // run
589	        this.executeShellCommand(this.toolType, `stcgal ${option.extraOptions} ${commands.join(' ')}`);
590	    }
591	}
