593	/**
594	 * STLink programer
595	*/
596	export type STLinkProtocolType = 'SWD' | 'JTAG';
597	
598	export interface STLinkOptions extends UploadOption {
599	
600	    proType: STLinkProtocolType;
601	
602	    address: string;
603	
604	    resetMode: string;
605	
606	    runAfterProgram: boolean;
607	
608	    speed: number;
609	
610	    elFile: string; /* external loader file */
611	
612	    optionBytes: string; /* option bytes file */
613	
614	    otherCmds: string;
615	}
616	
617	class STLinkUploader extends HexUploader<string[]> {
618	
619	    toolType: HexUploaderType = 'STLink';
620	
621	    DEF_BIN_ADDR = '0x08000000';
622	
623	    constructor(prj: AbstractProject) {
624	        super(prj);
625	    }
626	
627	    private genCommandForStlinkCli(exe: File, eraseAll?: boolean): string[] {
628	
629	        const commands: string[] = [];
630	        const options = this.getUploadOptions<STLinkOptions>();
631	        const programs = this.parseProgramFiles(options);
632	
633	        if (programs.length == 0) {
634	            throw new Error(`no any program files !`);
635	        }
636	
637	        /* connection commands */
638	        commands.push(
639	            '-c', options.proType, `FREQ=${options.speed.toString()}`, 'UR'
640	        );
641	
642	        /* reset mode */
643	        if (options.resetMode && options.resetMode != 'default') {
644	            const optMap: any = { 'SWrst': 'Srst', 'HWrst': 'Hrst' };
645	            commands.push(optMap[options.resetMode] || options.resetMode);
646	        }
647	
648	        /* flash commands */
649	        if (!eraseAll) {
650	
651	            commands.push(
652	                '-P', programs[0].path
653	            );
654	
655	            if (/\.bin$/i.test(programs[0].path)) {
656	                commands.push(programs[0].addr || options.address || this.DEF_BIN_ADDR);
657	            }
658	
659	            if (/\.stldr$/i.test(options.elFile)) {
660	                const elFolder = File.fromArray([NodePath.dirname(exe.path), 'ExternalLoader']);
661	                commands.push('-EL', options.elFile.replace('<stlink>', elFolder.path));
662	            }
663	
664	            // option bytes commands
665	            const optionFile = new File(this.project.ToAbsolutePath(options.optionBytes));
666	            if (optionFile.IsFile()) {
667	                const conf = <any>ini.parse(optionFile.Read());
668	                const confList: string[] = [];
669	                for (const key in conf) { confList.push(`${key}=${conf[key]}`) }
670	                if (confList.length > 0) {
671	                    commands.push('-OB');
672	                    confList.forEach((val) => { commands.push(val) });
673	                    commands.push('-rOB');
674	                }
675	            }
676	
677	            commands.push(
678	                '-V', 'after_programming'
679	            );
680	        }
681	
